    out = [row[:] for row in grid]

    # The vertical separator color appears as an entire column. The grid is
    # divided into equal-width panels; copy the marked pattern in the middle
    # panel into the corresponding positions of the other panels.
    sep = None
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            color = grid[0][c]
