                sep = color
                break

    if sep is None:
        return out

    separators = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    bounds = []
    start = 0
    for c in separators:
        if start < c:
            bounds.append((start, c))
        start = c + 1
    if start < w:
        bounds.append((start, w))

    if len(bounds) < 2:
        return out

    # Select the panel containing the densest non-background pattern.
    def count(panel):
        a, b = panel
        return sum(grid[r][c] not in (7, sep) for r in range(h) for c in range(a, b))

    source = max(range(len(bounds)), key=lambda i: count(bounds[i]))
    s0, s1 = bounds[source]
    for i, (a, b) in enumerate(bounds):
        if i == source:
            continue
        for r in range(h):
            for c in range(min(s1 - s0, b - a)):
                value = grid[r][s0 + c]
                if value != 7 and value != sep:
                    out[r][a + c] = value
    return out
