def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find grid-wide separator rows and columns (the divider color).
    sep = None
    for color in set(v for row in grid for v in row):
        if (any(all(grid[r][c] == color for c in range(w)) for r in range(h))
                or any(all(grid[r][c] == color for r in range(h)) for c in range(w))):
            sep = color
            break
    if sep is None:
        return out

    def make_bands(n, is_separator):
        bands, start = [], 0
        for i in range(n):
            if is_separator(i):
                if start < i:
                    bands.append((start, i))
                start = i + 1
        if start < n:
            bands.append((start, n))
        return bands

    rows = make_bands(h, lambda r: all(grid[r][c] == sep for c in range(w)))
    cols = make_bands(w, lambda c: all(grid[r][c] == sep for r in range(h)))
    if not rows or not cols:
        return out

    # Build the pattern of colored cells at relative positions within panels.
    pattern = {}
    for r0, r1 in rows:
        for c0, c1 in cols:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    value = grid[r][c]
                    if value != 7 and value != sep:
                        pattern[(r-r0, c-c0)] = value

    # Repeat each relative-position mark throughout every compartment.
    for r0, r1 in rows:
        for c0, c1 in cols:
            for (dr, dc), value in pattern.items():
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0+dr][c0+dc] = value
    return out
